When('the page is reloaded', function () {
  // Save current localStorage state
  const savedState = {};
  const ls = this.window.localStorage;
  for (let i = 0; i < ls.length; i++) {
    const k = ls.key(i);
    savedState[k] = ls.getItem(k);
  }
  // Reload the page
  reloadPage(this);
  // Restore localStorage state
  const newLs = this.window.localStorage;
  for (const k in savedState) {
    newLs.setItem(k, savedState[k]);
  }
  // Re-initialize the app with the restored state
  this.window.eval(`
    (function() {
      var STORAGE_KEY = 'todos-vanillajs';
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        // Trigger the app to reload from storage
        window.dispatchEvent(new Event('load'));
      }
    })()
  `);
});

